package lk.ac.sliit.ridelink.ride.infrastructure.client;
import lk.ac.sliit.ridelink.ride.application.usecase.*; import org.springframework.http.HttpStatusCode; import org.springframework.web.client.*; import java.net.SocketTimeoutException;
public final class ClientSupport {private ClientSupport(){}public static void status(String service,HttpStatusCode status){if(status.value()==409&&"Driver Service".equals(service))throw new DriverReservationConflictException("Driver became unavailable during assignment");throw new ExternalServiceException(service+" returned HTTP "+status.value(),false,null);}public static ExternalServiceException failure(String service,RuntimeException e){boolean timeout=e.getCause() instanceof SocketTimeoutException||e.getMessage()!=null&&e.getMessage().toLowerCase().contains("timed out");return new ExternalServiceException(service+(timeout?" timed out":" is unavailable"),timeout,e);}}
